WITH history AS (SELECT DATE_TRUNC(`event_date`, DAY) AS period, COUNT(*) AS cnt FROM `fake_project.dataset.orders` WHERE `event_date` >= DATE('2026-05-01') - INTERVAL 28 DAY AND `event_date` < DATE('2026-05-01') GROUP BY period) SELECT PERCENTILE_CONT(0.05) WITHIN GROUP (ORDER BY cnt) AS p_lo, PERCENTILE_CONT(0.95) WITHIN GROUP (ORDER BY cnt) AS p_hi, COUNT(*) AS n FROM history